/// <summary>
/// Base class for PricingAttribute table <c>ReqItemTable</c>
/// </summary>
internal abstract class METGUPPricingAttributeReqItemTable extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
    protected ReqItemTable getTableRecord(Common _pricingObject)
    {
        SalesLine		salesLine		= _pricingObject as SalesLine;
        ReqItemTable	reqItemTable	= ReqItemTable::find(salesLine.ItemId, salesLine.InventDimId);

        return reqItemTable;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsReqItemTable, qbdsInventTable;

        if (_qbdsMap && _qbdsMap.exists(tableStr(InventTable)))
        {
            qbdsInventTable = _qbdsMap.lookup(tableStr(InventTable));
        }
        else
        {
            qbdsInventTable = _query.addDataSource(tableNum(InventTable));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(InventTable), qbdsInventTable);
            }
        }

        if (_qbdsMap && _qbdsMap.exists(this.getQueryBuilderDatasourceIdentifier()))
        {
            qbdsReqItemTable = _qbdsMap.lookup(this.getQueryBuilderDatasourceIdentifier());
        }
        else
        {
            qbdsReqItemTable = qbdsInventTable.addDataSource(tableNum(ReqItemTable));
            qbdsReqItemTable.addLink(fieldNum(InventTable, ItemId), fieldNum(ReqItemTable, ItemId));
            qbdsReqItemTable.joinMode(JoinMode::ExistsJoin);
            
            if (_qbdsMap)
            {
                _qbdsMap.insert(this.getQueryBuilderDatasourceIdentifier(), qbdsReqItemTable);
            }
        }
        return qbdsReqItemTable;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }

    public GUPPricingAttributeTableFieldPath getPath()
    {
        return strFmt('%1#%2_%3$%4',
					tableStr(SalesLine),
					tableStr(ReqItemTable),
					fieldStr(SalesLine, ItemId),
					fieldStr(ReqItemTable, ItemId));
    }
